CREATE TABLE capital_type_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, capital_type text NOT NULL, fit_score integer NOT NULL DEFAULT 0, fit_state text NOT NULL DEFAULT 'not_assessed', rationale text, strengths jsonb NOT NULL DEFAULT '[]'::jsonb, blockers jsonb NOT NULL DEFAULT '[]'::jsonb, required_actions jsonb NOT NULL DEFAULT '[]'::jsonb, assessed_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id, capital_type));